from pathlib import Path
from html.parser import HTMLParser
import xml.etree.ElementTree as ET
from PIL import Image
root=Path('.')
print('manifest entries',len(root.joinpath('inputs.sha256').read_text().splitlines()))
for p in sorted(root.glob('figures/*.svg')):
 t=ET.parse(p).getroot()
 print('SVG',p,t.attrib)
 for e in t:
  if e.tag.endswith(('title','desc')):print(e.tag.split('}')[-1],e.text)
class P(HTMLParser):
 def handle_starttag(self,tag,attrs):
  d=dict(attrs)
  if tag=='img':print('IMG',d)
for p in (root/'pages/tracking-signal-retention.html',root/'pages/relative-phase-stability.html'):
 print('HTML',p);P().feed(p.read_text())
for d in ('chapter7','pilot-state'):
 for p in sorted((root/'pages'/d).glob('*.png')):
  with Image.open(p) as im: print('raster',p,im.size,'nonwhite bounds',Image.eval(im.convert('RGB'),lambda a:255-a).getbbox())
